class Solution:
    def fib(self, n: int) -> int:
        # Initialize memoization array with -1 for unknown values
        memo = [-1] * (n + 1)
        # Base cases
        memo[0] = 0
        if n >= 1:
            memo[1] = 1

        # Recursive helper with memoization
        def helper(k: int) -> int:
            if memo[k] != -1:
                return memo[k]
            memo[k] = helper(k - 1) + helper(k - 2)
            return memo[k]

        return helper(n)
