from typing import List
import collections

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words:
            return []
        wlen = len(words[0])
        total_len = wlen * len(words)
        occ = collections.Counter(words)
        res = []

        for offset in range(wlen):
            # Initialize track counter for this offset
            track = {word: 0 for word in words}
            # Build the first window starting at offset
            for i in range(offset, offset + total_len, wlen):
                if i + wlen > len(s):
                    break
                w = s[i:i+wlen]
                if w in track:
                    track[w] += 1
            # Check first window
            if track == occ:
                res.append(offset)
            # Slide the window
            for start in range(offset + wlen, len(s) - total_len + 1, wlen):
                # Add new word at the right
                new_word = s[start + total_len - wlen: start + total_len]
                if new_word in track:
                    track[new_word] += 1
                # Remove the leftmost word
                old_word = s[start - wlen: start]
