from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build trie of reversed forbidden strings for efficient backward check
        trie = {}
        for f in forbidden:
            t = trie
            for c in reversed(f):
                if c not in t:
                    t[c] = {}
                t = t[c]
            t["end"] = True

        left = 0
        res = 0
        for right in range(len(word)):
            node = trie
            # Check substrings ending at right by scanning leftwards
            for p in range(right, left - 1, -1):
                c = word[p]
                if c not in node:
                    break
                node = node[c]
                if "end" in node:
                    # Forbidden substring word[p:right+1] found
                    left = max(left, p + 1)
                    break
            res = max(res, right - left + 1)

        return res
