                break

        ans = []

        def fn(x):
            """Return Eulerian path via DFS."""
            while graph[x]:
                fn(graph[x].pop())
            ans.append(x)

        fn(start)
        ans.reverse()
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]
