    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        memo = {}

        def dp(i: int, prev: str, ct: int, k: int) -> int:
            if k < 0:
                return float('inf')
            if i >= n:
                if ct > 1:
                    return len(str(ct)) + 1
                elif ct == 1:
                    return 1
                else:
                    return 0
            key = (i, prev, ct, k)
            if key in memo:
                return memo[key]

            # keep current character
            if s[i] == prev:
                inc = dp(i + 1, prev, ct + 1, k)
            else:
                # finish previous group
                if ct > 1:
                    x = len(str(ct)) + 1
                elif ct == 1:
                    x = 1
                else:
                    x = 0
                inc = x + dp(i + 1, s[i], 1, k)

            # delete current character
            exc = dp(i + 1, prev, ct, k - 1)

            res = min(inc, exc)
            memo[key] = res
            return res

        return dp(0, '', 0, k)
