from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build trie of forbidden words
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node['#'] = True  # mark end of a forbidden word

        n = len(word)
        res = 0
        # For each starting index i, find the earliest forbidden prefix
        for i in range(n):
            node = trie
            # Extend as far as possible without hitting a forbidden word
            j = i
            while j < n and word[j] in node:
                node = node[word[j]]
                if '#' in node:
                    # Found a forbidden word covering s[i..j]
                    # So the longest valid substring starting at i is s[i..j-1]
                    break
                j += 1
            # If we exited due to a forbidden word, length = j - i (since j is the end index of forbidden)
            # Otherwise, j went to n, length = n - i
            res = max(res, j - i)
        return res
